<?php require_once __DIR__.'/_bootstrap.php';if($_SERVER['REQUEST_METHOD']!=='POST')apiError('Method not allowed');verifyCsrf();$tableId=filter_var(postField('table_id'),FILTER_VALIDATE_INT);$itemId=filter_var(postField('cafe_item_id'),FILTER_VALIDATE_INT);$quantity=max(1,(int)postField('quantity',1));if(!$tableId||!$itemId)apiError('Invalid menu selection.');$db=getDB();try{$db->beginTransaction();$q=$db->prepare("SELECT s.* FROM sessions s WHERE s.table_id=? AND s.club_id=? AND s.status IN ('running','paused') FOR UPDATE");$q->execute([$tableId,$_SESSION['club_id']]);$s=$q->fetch();if(!$s)throw new RuntimeException('Start a table session before adding café items.');$q=$db->prepare('SELECT * FROM cafe_items WHERE id=? AND club_id=? FOR UPDATE');$q->execute([$itemId,$_SESSION['club_id']]);$i=$q->fetch();if(!$i||$i['stock_quantity']<$quantity)throw new RuntimeException('This item is out of stock.');$q=$db->prepare("SELECT id FROM cafe_orders WHERE session_id=? AND status='open' LIMIT 1");$q->execute([$s['id']]);$orderId=$q->fetchColumn();if(!$orderId){$db->prepare("INSERT INTO cafe_orders(session_id,club_id,player_id,operator_id,total_amount,status) VALUES(?,?,?,?,0,'open')")->execute([$s['id'],$_SESSION['club_id'],$s['player_id'],$_SESSION['user_id']]);$orderId=$db->lastInsertId();}$subtotal=$i['price']*$quantity;$db->prepare('INSERT INTO cafe_order_items(order_id,cafe_item_id,item_name,item_price,quantity,subtotal) VALUES(?,?,?,?,?,?)')->execute([$orderId,$i['id'],$i['name'],$i['price'],$quantity,$subtotal]);$db->prepare('UPDATE cafe_orders SET total_amount=total_amount+? WHERE id=?')->execute([$subtotal,$orderId]);$db->prepare('UPDATE cafe_items SET stock_quantity=stock_quantity-? WHERE id=?')->execute([$quantity,$i['id']]);$db->prepare('UPDATE sessions SET cafe_amount=cafe_amount+? WHERE id=?')->execute([$subtotal,$s['id']]);if(($i['stock_quantity']-$quantity)<=$i['low_stock_threshold'])$db->prepare('INSERT INTO notifications(club_id,type,message) VALUES(?,?,?)')->execute([$_SESSION['club_id'],'low_stock',$i['name'].' is running low ('.($i['stock_quantity']-$quantity).' left).']);$db->commit();jsonResponse(true,$i['name'].' added to table bill.');}catch(Throwable $e){if($db->inTransaction())$db->rollBack();apiError($e->getMessage());}
